def announce(func):
    def wrapper():
        print(">> Before function runs")
        func()
        print(">> After function finishes")
    return wrapper

@announce
def greet():
    print("Hello world!")

greet()

# Generator function with yield
def count_down(start):
    while start > 0:
        yield start
        start -= 1

for n in count_down(3):
    print(n, end=" ")
print()

def trace(func):
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__} with {args}")
        return func(*args, **kwargs)
    return wrapper

@trace
def add(a, b):
    return a + b

print("Result:", add(3, 4))

# Proper wrapper return pattern
def double_result(func):
    def wrapper(*args, **kwargs):
        res = func(*args, **kwargs)
        return res * 2
    return wrapper

@double_result
def get_val():
    return 21
print("Doubled:", get_val())

import functools
def clean_dec(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

